//! Icons for apps on the landing page and in the app: a built-in name
//! (`grafana`), a file in the project or workspace repo (`assets/logo.svg`),
//! or an image URL. Without one, a container's image picks a built-in icon
//! (`postgres:17` gets PostgreSQL's).
//!
//! The built-in set is `icons.json`, generated by `scripts/gen-icons.mjs`
//! and shared with the app (`gui/src/lib/icons.json`).

use std::collections::HashMap;
use std::path::Path;
use std::sync::LazyLock;

use base64::Engine;
use serde::Deserialize;

#[derive(Deserialize)]
struct IconSet {
    icons: HashMap<String, Icon>,
    aliases: HashMap<String, String>,
    images: Vec<(String, String)>,
}

#[derive(Deserialize)]
struct Icon {
    #[allow(dead_code)]
    title: String,
    svg: String,
}

static SET: LazyLock<IconSet> =
    LazyLock::new(|| serde_json::from_str(include_str!("icons.json")).expect("icons.json is valid"));

/// The largest icon file read from a repo.
pub const MAX_FILE_BYTES: u64 = 64 * 1024;

/// A built-in icon's canonical name, from its name or an alias.
pub fn builtin(name: &str) -> Option<&'static str> {
    let n = name.trim().to_ascii_lowercase();
    let n = SET.aliases.get(&n).cloned().unwrap_or(n);
    SET.icons.get_key_value(&n).map(|(k, _)| k.as_str())
}

/// The built-in icon for a container image, if one fits: by its path
/// without registry and tag (`grafana/grafana`), else by its last part.
pub fn for_image(image: &str) -> Option<&'static str> {
    let image = image.split('@').next().unwrap_or(image);
    // The tag is after the last ':' that comes after the last '/'.
    let name = match image.rfind(':') {
        Some(i) if i > image.rfind('/').unwrap_or(0) => &image[..i],
        _ => image,
    };
    let mut parts: Vec<&str> = name.split('/').collect();
    if parts.len() > 1 && (parts[0].contains('.') || parts[0].contains(':') || parts[0] == "localhost") {
        parts.remove(0);
    }
    if parts.first() == Some(&"library") {
        parts.remove(0);
    }
    let path = parts.join("/").to_ascii_lowercase();
    let last = parts.last().map(|s| s.to_ascii_lowercase()).unwrap_or_default();
    let find = |key: &str| SET.images.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str());
    find(&path)
        .or_else(|| find(&last))
        .and_then(|n| SET.icons.get_key_value(n).map(|(k, _)| k.as_str()))
}

/// What a route keeps from an `icon:` setting: a URL as given, a built-in
/// name, or a repo file (relative to `base`) read into a `data:` URL; the
/// reason when it's none of these.
pub fn resolve(spec: &str, base: Option<&Path>) -> Result<String, String> {
    let spec = spec.trim();
    if spec.starts_with("https://") || spec.starts_with("data:image/") {
        return Ok(spec.to_string());
    }
    let ext = Path::new(spec)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase());
    let mime = match ext.as_deref() {
        Some("svg") => Some("image/svg+xml"),
        Some("png") => Some("image/png"),
        Some("webp") => Some("image/webp"),
        Some("jpg" | "jpeg") => Some("image/jpeg"),
        _ => None,
    };
    if let Some(mime) = mime.filter(|_| spec.contains('/') || spec.contains('.')) {
        let base = base.ok_or_else(|| format!("icon {spec}: a file needs a project folder"))?;
        let rel = Path::new(spec);
        if rel.is_absolute() || rel.components().any(|c| matches!(c, std::path::Component::ParentDir)) {
            return Err(format!("icon {spec}: use a path inside the folder"));
        }
        let path = base.join(rel);
        let len = std::fs::metadata(&path)
            .map_err(|_| format!("icon {spec}: no such file"))?
            .len();
        if len > MAX_FILE_BYTES {
            return Err(format!("icon {spec}: larger than {} KB", MAX_FILE_BYTES / 1024));
        }
        let bytes = std::fs::read(&path).map_err(|e| format!("icon {spec}: {e}"))?;
        return Ok(format!(
            "data:{mime};base64,{}",
            base64::engine::general_purpose::STANDARD.encode(bytes)
        ));
    }
    builtin(spec)
        .map(str::to_string)
        .ok_or_else(|| format!("icon {spec}: not a built-in icon, an image file or an https URL"))
}

/// An `<img src>` for a kept icon: URLs as they are, built-in names as a
/// `data:` URL of their SVG.
pub fn src(icon: &str) -> Option<String> {
    if icon.starts_with("https://") || icon.starts_with("data:image/") {
        return Some(icon.to_string());
    }
    let svg = &SET.icons.get(builtin(icon)?)?.svg;
    Some(format!(
        "data:image/svg+xml;base64,{}",
        base64::engine::general_purpose::STANDARD.encode(svg)
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn images_pick_icons() {
        assert_eq!(for_image("postgres:17"), Some("postgresql"));
        assert_eq!(for_image("docker.io/library/redis:7-alpine"), Some("redis"));
        assert_eq!(for_image("grafana/grafana:latest"), Some("grafana"));
        assert_eq!(for_image("quay.io/keycloak/keycloak:26.0"), Some("keycloak"));
        assert_eq!(for_image("localhost:5000/nginx"), Some("nginx"));
        assert_eq!(for_image("axllent/mailpit"), Some("mailpit"));
        assert_eq!(for_image("acme/shop-web:dev"), None);
    }

    #[test]
    fn specs_resolve() {
        assert_eq!(resolve("Postgres", None).unwrap(), "postgresql");
        assert_eq!(resolve("https://x.dev/a.png", None).unwrap(), "https://x.dev/a.png");
        assert!(resolve("nope", None).is_err());
        assert!(resolve("../x.svg", Some(Path::new("/tmp"))).is_err());
        let dir = std::env::temp_dir().join(format!("orca-icon-{}", std::process::id()));
        std::fs::create_dir_all(dir.join("assets")).unwrap();
        std::fs::write(dir.join("assets/logo.svg"), "<svg/>").unwrap();
        assert!(
            resolve("assets/logo.svg", Some(&dir))
                .unwrap()
                .starts_with("data:image/svg+xml;base64,")
        );
        std::fs::remove_dir_all(&dir).unwrap();
        assert!(src("grafana").unwrap().starts_with("data:image/svg+xml;base64,"));
        assert_eq!(src("javascript:alert(1)"), None);
    }

    #[test]
    fn every_image_rule_and_alias_names_an_icon() {
        for (_, n) in &SET.images {
            assert!(SET.icons.contains_key(n), "{n}");
        }
        for n in SET.aliases.values() {
            assert!(SET.icons.contains_key(n), "{n}");
        }
    }
}
